def calculate(s):
    stack = []
    num = 0
    op = '+'
    s = s.replace(" ", "")
    for i, ch in enumerate(s):
        if ch.isdigit():
            num = num * 10 + int(ch)
        if not ch.isdigit() or i == len(s) - 1:
            if op == '+':
                stack.append(num)
            elif op == '-':
                stack.append(-num)
            elif op == '*':
                stack.append(stack.pop() * num)
            elif op == '/':
                top = stack.pop()
                if top < 0:
                    stack.append(-(-top // num))
                else:
                    stack.append(top // num)
            op = ch
            num = 0
    return sum(stack)
